-- Tables, keys and declarative constraints. Rules that need to read other rows or tables are
-- triggers in 02_rules.sql. Every constraint is named; business-rule constraints are brNN_<what>
-- (rule list: .claude/plan.md §3).
-- Surrogate keys are GENERATED BY DEFAULT so the reference seed can pin a few ids (see 10_seed_reference.sql).

-- ---------------------------------------------------------------- customers

CREATE TABLE customer (
    customer_id INT GENERATED BY DEFAULT AS IDENTITY,
    email       email_address NOT NULL,
    full_name   TEXT          NOT NULL,
    phone       TEXT,
    created_at  TIMESTAMPTZ   NOT NULL DEFAULT now(),
    CONSTRAINT customer_pk PRIMARY KEY (customer_id),
    CONSTRAINT br01_customer_email_unique UNIQUE (email)
);

-- Weak entity of customer: address_no only identifies an address within one customer.
CREATE TABLE customer_address (
    customer_id INT         NOT NULL,
    address_no  INT         NOT NULL,
    line1       TEXT        NOT NULL,
    suburb      TEXT        NOT NULL,
    state       au_state    NOT NULL,
    postcode    au_postcode NOT NULL,
    is_active   BOOLEAN     NOT NULL DEFAULT TRUE,   -- BR16: "editing" = deactivate this one, add a new one
    CONSTRAINT customer_address_pk PRIMARY KEY (customer_id, address_no),
    CONSTRAINT customer_address_customer_fk FOREIGN KEY (customer_id)
        REFERENCES customer (customer_id) ON DELETE CASCADE,
    CONSTRAINT customer_address_no_positive CHECK (address_no > 0)
);

-- ---------------------------------------------------------------- stores and staff

CREATE TABLE store (
    store_id   INT GENERATED BY DEFAULT AS IDENTITY,
    name       TEXT     NOT NULL,
    store_type TEXT     NOT NULL,
    suburb     TEXT     NOT NULL,
    state      au_state NOT NULL,
    manager_id INT      NOT NULL,                    -- BR04: its FK is added after staff exists
    CONSTRAINT store_pk PRIMARY KEY (store_id),
    CONSTRAINT store_name_unique UNIQUE (name),
    CONSTRAINT store_type_valid CHECK (store_type IN ('retail', 'warehouse'))
);

-- ISA (store employee / support staff) mapped to one table with a discriminator (plan T-4).
CREATE TABLE staff (
    staff_id   INT GENERATED BY DEFAULT AS IDENTITY,
    store_id   INT,
    staff_type TEXT          NOT NULL,
    full_name  TEXT          NOT NULL,
    email      email_address NOT NULL,
    CONSTRAINT staff_pk PRIMARY KEY (staff_id),
    CONSTRAINT staff_email_unique UNIQUE (email),
    -- Implied by the PK, but gives composite FKs a target: "staff member X *of store S*" (BR04, BR18).
    CONSTRAINT staff_store_staff_unique UNIQUE (store_id, staff_id),
    CONSTRAINT staff_store_fk FOREIGN KEY (store_id) REFERENCES store (store_id),
    CONSTRAINT staff_type_valid CHECK (staff_type IN ('store', 'support')),
    CONSTRAINT br05_staff_store_matches_type CHECK ((staff_type = 'support') = (store_id IS NULL))
);

-- BR04: a store's manager works at that store. store and staff reference each other, so this FK is
-- checked at COMMIT (DEFERRED): a new store and its manager are inserted in the same transaction.
ALTER TABLE store ADD CONSTRAINT br04_store_manager_works_here
    FOREIGN KEY (store_id, manager_id) REFERENCES staff (store_id, staff_id)
    DEFERRABLE INITIALLY DEFERRED;

-- A sign-in identity (the verified token's subject — for Clerk, "user_2ab…") and who it is in our data.
-- BR19: exactly one customer or one staff member per identity, and at most one identity per person.
-- Roles are not stored here: they stay where they are (staff.staff_type, staff.store_id, store.manager_id).
CREATE TABLE user_account (
    auth_subject TEXT        NOT NULL,
    customer_id  INT,
    staff_id     INT,
    linked_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT user_account_pk PRIMARY KEY (auth_subject),
    CONSTRAINT br19_account_one_customer UNIQUE (customer_id),
    CONSTRAINT br19_account_one_staff    UNIQUE (staff_id),
    CONSTRAINT user_account_customer_fk  FOREIGN KEY (customer_id) REFERENCES customer (customer_id),
    CONSTRAINT user_account_staff_fk     FOREIGN KEY (staff_id)    REFERENCES staff (staff_id),
    CONSTRAINT br19_account_customer_xor_staff CHECK ((customer_id IS NULL) <> (staff_id IS NULL))
);

-- ---------------------------------------------------------------- catalogue

CREATE TABLE category (
    category_id INT GENERATED BY DEFAULT AS IDENTITY,
    name        TEXT NOT NULL,
    parent_id   INT,                                 -- recursive relationship; NULL = top level
    CONSTRAINT category_pk PRIMARY KEY (category_id),
    CONSTRAINT category_name_unique UNIQUE (name),
    CONSTRAINT category_parent_fk FOREIGN KEY (parent_id) REFERENCES category (category_id),
    CONSTRAINT category_not_own_parent CHECK (parent_id <> category_id)
);

CREATE TABLE brand (
    brand_id INT GENERATED BY DEFAULT AS IDENTITY,
    name     TEXT NOT NULL,
    CONSTRAINT brand_pk PRIMARY KEY (brand_id),
    CONSTRAINT brand_name_unique UNIQUE (name)
);

-- One row per SKU. The brand is not repeated in name (it is brand_id's job).
CREATE TABLE product (
    product_id  INT GENERATED BY DEFAULT AS IDENTITY,
    sku         TEXT      NOT NULL,
    name        TEXT      NOT NULL,
    brand_id    INT       NOT NULL,
    category_id INT       NOT NULL,
    base_price  money_aud NOT NULL,
    is_active   BOOLEAN   NOT NULL DEFAULT TRUE,     -- retired, never deleted: orders reference products
    CONSTRAINT product_pk PRIMARY KEY (product_id),
    CONSTRAINT product_sku_unique UNIQUE (sku),
    CONSTRAINT product_sku_format CHECK (sku ~ '^[A-Z0-9]+(-[A-Z0-9]+)*$'),
    CONSTRAINT product_brand_fk FOREIGN KEY (brand_id) REFERENCES brand (brand_id),
    CONSTRAINT product_category_fk FOREIGN KEY (category_id) REFERENCES category (category_id)
);

-- Weak entity of product: key-value specs (plan T-5), at most one value per spec name.
CREATE TABLE product_spec (
    product_id INT  NOT NULL,
    spec_name  TEXT NOT NULL,
    spec_value TEXT NOT NULL,
    CONSTRAINT product_spec_pk PRIMARY KEY (product_id, spec_name),
    CONSTRAINT product_spec_product_fk FOREIGN KEY (product_id)
        REFERENCES product (product_id) ON DELETE CASCADE
);

-- A promotion runs over the half-open period [starts_at, ends_at).
-- BR15 (below the base price, no overlap) needs other rows: see 02_rules.sql.
CREATE TABLE promotion (
    promotion_id INT GENERATED BY DEFAULT AS IDENTITY,
    product_id   INT         NOT NULL,
    sale_price   money_aud   NOT NULL,
    starts_at    TIMESTAMPTZ NOT NULL,
    ends_at      TIMESTAMPTZ NOT NULL,
    CONSTRAINT promotion_pk PRIMARY KEY (promotion_id),
    CONSTRAINT promotion_product_fk FOREIGN KEY (product_id) REFERENCES product (product_id),
    CONSTRAINT promotion_period_valid CHECK (starts_at < ends_at)
);

-- ---------------------------------------------------------------- stock

-- M:N relationship between store and product, with the attribute quantity.
CREATE TABLE inventory (
    store_id   INT NOT NULL,
    product_id INT NOT NULL,
    quantity   INT NOT NULL DEFAULT 0,
    CONSTRAINT inventory_pk PRIMARY KEY (store_id, product_id),
    CONSTRAINT inventory_store_fk FOREIGN KEY (store_id) REFERENCES store (store_id),
    CONSTRAINT inventory_product_fk FOREIGN KEY (product_id) REFERENCES product (product_id),
    CONSTRAINT br03_inventory_qty_nonneg CHECK (quantity >= 0)
);

-- BR18: every manual stock change is logged — who (staff of that store), why, by how much, and the
-- quantity it left. app/services/inventory.py writes it in the same transaction as the inventory
-- update; the log is append-only (02_rules.sql).
CREATE TABLE stock_adjustment (
    adjustment_id  INT GENERATED BY DEFAULT AS IDENTITY,
    store_id       INT         NOT NULL,
    product_id     INT         NOT NULL,
    staff_id       INT         NOT NULL,
    delta          INT         NOT NULL,
    reason         TEXT        NOT NULL,
    note           TEXT,
    quantity_after INT         NOT NULL,             -- snapshot for the audit trail (like order_line.unit_price)
    adjusted_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT stock_adjustment_pk PRIMARY KEY (adjustment_id),
    CONSTRAINT stock_adjustment_inventory_fk FOREIGN KEY (store_id, product_id)
        REFERENCES inventory (store_id, product_id),
    CONSTRAINT br18_adjustment_staff_at_store FOREIGN KEY (store_id, staff_id)
        REFERENCES staff (store_id, staff_id),
    CONSTRAINT br18_adjustment_delta_matches_reason CHECK (
           (reason = 'received'  AND delta > 0)          -- delivery from a supplier
        OR (reason = 'damaged'   AND delta < 0)          -- written off: damaged, lost, stolen
        OR (reason = 'stocktake' AND delta <> 0)),       -- correction after a count
    CONSTRAINT stock_adjustment_quantity_after_nonneg CHECK (quantity_after >= 0)
);

-- ---------------------------------------------------------------- orders

-- Allowed status moves per fulfilment method, stored as data (BR09). Rows: 02_rules.sql.
CREATE TABLE order_status_transition (
    fulfilment_method fulfilment   NOT NULL,
    from_status       order_status NOT NULL,
    to_status         order_status NOT NULL,
    CONSTRAINT order_status_transition_pk PRIMARY KEY (fulfilment_method, from_status, to_status)
);

-- "order" is a reserved word.
CREATE TABLE customer_order (
    order_id            INT GENERATED BY DEFAULT AS IDENTITY,
    customer_id         INT          NOT NULL,
    idempotency_key     UUID         NOT NULL,
    fulfilment_method   fulfilment   NOT NULL,
    fulfilling_store_id INT          NOT NULL,       -- ships from (delivery) or is collected at (C&C)
    delivery_address_no INT,
    status              order_status NOT NULL DEFAULT 'placed',
    placed_at           TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT customer_order_pk PRIMARY KEY (order_id),
    CONSTRAINT customer_order_customer_fk FOREIGN KEY (customer_id) REFERENCES customer (customer_id),
    CONSTRAINT customer_order_store_fk FOREIGN KEY (fulfilling_store_id) REFERENCES store (store_id),
    CONSTRAINT br10_order_idempotency_unique UNIQUE (customer_id, idempotency_key),
    CONSTRAINT br06_order_address_matches_method
        CHECK ((fulfilment_method = 'delivery') = (delivery_address_no IS NOT NULL)),
    -- Composite FK: the address must be one of *this customer's* addresses.
    CONSTRAINT br17_order_address_is_customers FOREIGN KEY (customer_id, delivery_address_no)
        REFERENCES customer_address (customer_id, address_no)
);

-- Weak entity of customer_order.
CREATE TABLE order_line (
    order_id   INT       NOT NULL,
    line_no    INT       NOT NULL,
    product_id INT       NOT NULL,
    quantity   INT       NOT NULL,
    unit_price money_aud NOT NULL,                   -- BR08: the price at purchase time (plan T-1)
    CONSTRAINT order_line_pk PRIMARY KEY (order_id, line_no),
    CONSTRAINT order_line_order_fk FOREIGN KEY (order_id)
        REFERENCES customer_order (order_id) ON DELETE CASCADE,
    CONSTRAINT order_line_product_fk FOREIGN KEY (product_id) REFERENCES product (product_id),
    CONSTRAINT br07_order_line_qty_positive CHECK (quantity > 0),
    CONSTRAINT br07_order_line_product_once UNIQUE (order_id, product_id)
);

-- Audit trail (R11). Only the BR09 trigger writes it.
CREATE TABLE order_status_history (
    order_id            INT          NOT NULL,
    seq                 INT          NOT NULL,
    from_status         order_status,                -- NULL on the row that records the order's creation
    to_status           order_status NOT NULL,
    changed_at          TIMESTAMPTZ  NOT NULL DEFAULT now(),
    changed_by_staff_id INT,                         -- NULL when the customer or the system made the change
    CONSTRAINT order_status_history_pk PRIMARY KEY (order_id, seq),
    CONSTRAINT order_status_history_order_fk FOREIGN KEY (order_id)
        REFERENCES customer_order (order_id) ON DELETE CASCADE,
    CONSTRAINT order_status_history_staff_fk FOREIGN KEY (changed_by_staff_id) REFERENCES staff (staff_id),
    -- BR09: row 1 records the order's creation and is the only row without a from_status, and every row
    -- records a real change.
    CONSTRAINT br09_history_first_row_is_creation CHECK ((seq = 1) = (from_status IS NULL)),
    CONSTRAINT br09_history_status_changes CHECK (from_status IS DISTINCT FROM to_status)
);

-- ---------------------------------------------------------------- returns and payments

CREATE TABLE return_request (
    return_id             INT GENERATED BY DEFAULT AS IDENTITY,
    order_id              INT         NOT NULL,
    status                TEXT        NOT NULL DEFAULT 'requested',
    reason                TEXT        NOT NULL,
    requested_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    received_store_id     INT,
    processed_by_staff_id INT,
    CONSTRAINT return_request_pk PRIMARY KEY (return_id),
    CONSTRAINT return_request_order_unique UNIQUE (return_id, order_id),  -- target of composite FKs below
    CONSTRAINT return_request_order_fk FOREIGN KEY (order_id) REFERENCES customer_order (order_id),
    CONSTRAINT return_request_store_fk FOREIGN KEY (received_store_id) REFERENCES store (store_id),
    CONSTRAINT return_request_processor_at_store FOREIGN KEY (received_store_id, processed_by_staff_id)
        REFERENCES staff (store_id, staff_id),
    CONSTRAINT return_request_status_valid CHECK (status IN ('requested', 'received', 'refunded', 'rejected')),
    CONSTRAINT return_request_receipt_recorded CHECK (
        status NOT IN ('received', 'refunded')
        OR (received_store_id IS NOT NULL AND processed_by_staff_id IS NOT NULL))
);

-- order_id is copied from the return so a composite FK can require "same order" (BR13 —
-- controlled redundancy, plan T-3).
CREATE TABLE return_line (
    return_id INT NOT NULL,
    line_no   INT NOT NULL,
    order_id  INT NOT NULL,
    quantity  INT NOT NULL,
    CONSTRAINT return_line_pk PRIMARY KEY (return_id, line_no),
    CONSTRAINT br13_return_line_same_order FOREIGN KEY (return_id, order_id)
        REFERENCES return_request (return_id, order_id) ON DELETE CASCADE,
    CONSTRAINT return_line_order_line_fk FOREIGN KEY (order_id, line_no)
        REFERENCES order_line (order_id, line_no),
    CONSTRAINT return_line_qty_positive CHECK (quantity > 0)
);

CREATE TABLE payment (
    payment_id INT GENERATED BY DEFAULT AS IDENTITY,
    order_id   INT         NOT NULL,
    kind       TEXT        NOT NULL,
    amount     money_aud   NOT NULL,
    return_id  INT,                                  -- refunds only
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT payment_pk PRIMARY KEY (payment_id),
    CONSTRAINT payment_order_fk FOREIGN KEY (order_id) REFERENCES customer_order (order_id),
    CONSTRAINT payment_kind_valid CHECK (kind IN ('charge', 'refund')),
    CONSTRAINT payment_amount_positive CHECK (amount > 0),
    CONSTRAINT br14_refund_has_return CHECK ((kind = 'refund') = (return_id IS NOT NULL)),
    CONSTRAINT br14_refund_once_per_return UNIQUE (return_id),
    -- A refund's return must belong to the order being refunded.
    CONSTRAINT payment_return_same_order FOREIGN KEY (return_id, order_id)
        REFERENCES return_request (return_id, order_id)
);

-- BR20: an order is charged at most once (the rest of BR20 is in 02_rules.sql). A partial unique index is
-- UNIQUE over only the rows its WHERE matches, so it doesn't limit an order's refunds. Beyond Week 10
-- (optional, plan T-8): without it BR20's paid-in-full trigger would still refuse to mark an over-charged
-- order paid; the index refuses the second charge itself.
CREATE UNIQUE INDEX br20_one_charge_per_order ON payment (order_id) WHERE kind = 'charge';
